
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='api_frequency_stat' and xtype='U')
CREATE TABLE api_frequency_stat (
    id BIGINT IDENTITY(1,1) PRIMARY KEY,
    name NVARCHAR(255),
    path NVARCHAR(255),
    total INT,
    success INT,
    error400 INT,
    error_customer INT,
    error_system INT
);

TRUNCATE TABLE api_frequency_stat;
